    List<List<Integer>> result = new ArrayList<>();
    if (nums.length == 1) {
        result.add(Arrays.asList(nums));
    } else {
        for (int i = 0; i < nums.length; i++) {
            int[] newNums = new int[nums.length - 1];
            System.arraycopy(nums, 0, newNums, 0, i);
            System.arraycopy(nums, i + 1, newNums, i, newNums.length - i);
            List<List<Integer>> subPermutations = permute(newNums);
            for (int j = 0; j < subPermutations.size(); j++) {
                List<Integer> newSubList = new ArrayList<>(subPermutations.get(j));
                newSubList.add(0, nums[i]);
                result.add(newSubList);
            }
        }
    }
    return result;
}

