    // Find the longest string
    String longestString = strings.stream().max(Comparator.comparingInt(String::length)).orElse(null);

    // Find the largest substring
    int largestSubstringLength = 0;
    for (String string : strings) {
        if (string.contains(longestString)) {
            largestSubstringLength = Math.max(largestSubstringLength, string.length());
        } else if (longestString.contains(string)) {
            largestSubstringLength = Math.max(largestSubstringLength, string.length());
        }
    }

    return largestSubstringLength;
}

