public static int countOilDeposits(char[][] grid) {
    // Initialize a hash set to store unique oil deposit coordinates
    Set<String> oilDeposits = new HashSet<>();

    // Iterate over each row of the grid
    for (int i = 0; i < grid.length; i++) {
        // Iterate over each column of the current row
        for (int j = 0; j < grid[i].length; j++) {
            // If the current cell is an oil pocket, add its coordinates to the hash set
            if (grid[i][j] == '@') {
                oilDeposits.add(i + "," + j);
            }
        }
    }

    // Return the size of the hash set, which is the number of distinct oil deposits
    return oilDeposits.size();
}

