  // Find the maximum number of regions by testing all possible edge cases
  // between 1 and N, inclusive. The number of regions should be N(N-1)/2.
  int maxRegions = 0;
  for (int i = 1; i <= N; i++) {
    for (int j = i; j <= N; j++) {
      maxRegions = Math.max(maxRegions, (i * (N - i)) / 2);
    }
  }
  return maxRegions;
}

