public double trimMean(int[] arr) {
  // sort the array in ascending order
  Arrays.sort(arr);

  // calculate the sum of the first and last 5% of elements
  int sumFirst5Percent = 0;
  int sumLast5Percent = 0;
  int totalElements = arr.length;
  int first5Percent = (int) (totalElements * 0.05);
  int last5Percent = (int) (totalElements * 0.05);
  for (int i = 0; i < first5Percent; i++) {
    sumFirst5Percent += arr[i];
  }
  for (int i = totalElements - last5Percent; i < totalElements; i++) {
    sumLast5Percent += arr[i];
  }

  // calculate the mean of the remaining elements
  double mean = sumFirst5Percent + sumLast5Percent;
  mean /= totalElements - (first5Percent + last5Percent);

  return mean;
}

