public static double trimMean(int[] arr) {
    // Find the number of elements to remove from the smallest and largest 5% of the array
    // The number of elements to remove should be at most 10% of the total elements in the array
    int n = arr.length;
    int smallest5pcnt = (int) Math.ceil(n * 0.05);
    int largest5pcnt = (int) Math.ceil(n * 0.05);
    int smallestToRemove = Math.min(smallest5pcnt, n / 10);
    int largestToRemove = Math.min(largest5pcnt, n / 10);

    // Sort the array in ascending order
    Arrays.sort(arr);

    // Trim the smallest and largest 5% of the array
    int[] trimmedArr = new int[n - smallestToRemove - largestToRemove];
    System.arraycopy(arr, smallestToRemove, trimmedArr, 0, n - smallestToRemove - largestToRemove);
    System.arraycopy(arr, n - largestToRemove, trimmedArr, n - smallestToRemove - largestToRemove, largestToRemove);

    // Calculate the mean of the trimmed array
    double mean = 0;
    for (int i = 0; i < trimmedArr.length; i++) {
        mean += trimmedArr[i];
    }
    mean /= trimmedArr.length;

    // Return the mean with an error within 10^-5
    return mean;
  }

