public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Initialize a graph and a queue to store the nodes
    Graph graph = new Graph(n);
    Queue<Integer> queue = new LinkedList<>();

    // Add all the edges and the initial node
    for (int[] edge : edges) {
        graph.addEdge(edge[0], edge[1]);
    }
    queue.add(0);

    // Initialize a map to store the nodes and their distances
    Map<Integer, Integer> distances = new HashMap<>();
    distances.put(0, 0);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node and its distance
        int node = queue.remove();
        int distance = distances.get(node);

        // Add the node's neighbors to the queue and update their distances
        for (int neighbor : graph.neighbors(node)) {
            if (!distances.containsKey(neighbor)) {
                queue.add(neighbor);
                distances.put(neighbor, distance + 1);
            }
        }
    }

    // Initialize the minimum time to collect all the apples and the current time
    int minTime = 0, currentTime = 0;

    // Loop through the nodes and calculate the minimum time to collect all the apples
    for (int node = 0; node < n; node++) {
        if (hasApple[node]) {
            minTime = Math.max(minTime, currentTime + distances.get(node));
        }
        currentTime += distances.get(node);
    }

    return minTime;
}

