    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // Calculate the average of the input array
    int average = sum / nums.length;

    // Initialize two variables to keep track of the sum of the left and right subarrays
    int leftSum = 0, rightSum = 0;

    // Iterate through the input array
    for (int i = 0; i < nums.length; i++) {
        // Add the current element to the left subarray sum
        leftSum += nums[i];

        // If the left subarray sum is greater than the average, remove the last element from the left subarray
        while (leftSum > average) {
            leftSum -= nums[i - 1];
        }

        // Add the current element to the right subarray sum
        rightSum += nums[i];

        // If the right subarray sum is greater than the average, remove the first element from the right subarray
        while (rightSum > average) {
            rightSum -= nums[0];
        }

        // If the left and right subarray sums are equal, return true
        if (leftSum == rightSum) {
            return true;
        }
    }

    // If no split was found, return false
    return false;
}

