public static int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }

    // Initialize the first two Fibonacci numbers
    int fib1 = 1;
    int fib2 = 1;

    // Loop through the Fibonacci sequence until we find a number
    // that is greater than or equal to k
    while (fib1 + fib2 < k) {
        int newFib = fib1 + fib2;
        fib1 = fib2;
        fib2 = newFib;
    }

    // Return the minimum number of Fibonacci numbers required
    // to sum up to k
    return Math.min(fib2 == k ? 2 : 3, k / fib2 + (k % fib2 == 0 ? 0 : 1));
}

