public int findMinFibonacciNumbers(int k) {
    int[] fib = new int[]{1, 1};
    int n = 2;

    while (k > fib[n - 1]) {
        fib[n] = fib[n - 1] + fib[n - 2];
        n++;
    }

    if (k == fib[n - 1]) {
        return n - 1;
    }

    int m = n - 2;
    int sum = fib[m];

    while (sum < k) {
        sum += fib[m];
        m--;
    }

    return m + 1;
}

