public int kthFactor(int n, int k) {
    // Create an array to store the factors of n
    ArrayList<Integer> factors = new ArrayList<>();

    // Iterate from 1 to the square root of n
    for (int i = 1; i * i <= n; i++) {
        // If i is a factor of n, add it to the array
        if (n % i == 0) {
            factors.add(i);

            // If i is not the number itself, add its inverse as well
            if (i != n / i) {
                factors.add(n / i);
            }
        }
    }

    // Sort the factors in ascending order
    Collections.sort(factors);

    // Return the kth factor or -1 if there are fewer than k factors
    if (factors.size() < k) {
        return -1;
    } else {
        return factors.get(k - 1);
    }
}

