    }

    while (!que.isEmpty()) {
        String num = que.poll();
        int lastDigit = num.charAt(num.length() - 1) - '0';
        if (lastDigit > 0) {
            que.offer(num + (lastDigit - 1));
        }
        if (lastDigit < 9) {
            que.offer(num + (lastDigit + 1));
        }
    }

    for (int i = low; i <= high; i++) {
        if (steppingNumbers.contains(i)) {
            steppingNumbers.add(i);
        }
    }

    Collections.sort(steppingNumbers);
    return steppingNumbers;
}

