public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The index must be a positive integer.");
    }

    int[] factors = new int[3];
    factors[0] = 2;
    factors[1] = 3;
    factors[2] = 5;
    LinkedList<Integer> uglyNumbers = new LinkedList<>();
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 0; j < factors.length; j++) {
            int factor = factors[j];
            int product = factor * (factors[j] - 1);
            if (product < min && product < Integer.MAX_VALUE - 1) {
                min = product;
            }
        }
        uglyNumbers.addFirst(min);
        for (int j = 0; j < factors.length; j++) {
            factors[j] *= factors[j];
        }
    }
    return uglyNumbers.get(n - 1);
}

